function frameRateFor(frameColor, rates) {
  return frameColor === "White" ? rates.frameFt : rates.frameFtColor;
}

// Flags real data gaps on an order — a whole-door job with no price set, a custom-priced
// tier switched on but left at $0 (an easy typo), missing contact info, or the one original
// Metro Screenworks case. Shared between the Inbox display and the Inbox badge count so
// they can never disagree with each other.
function getMissingDetails(o) {
  const missing = [];
  if (o.fullPatioReplacement && o.metroStatus === "ordered" && !o.subcontractorOrderedDate && !o.subcontractorJobNumber) {
    missing.push("Metro date & job #");
  }
  if (o.fullPatioReplacement && !(Number(o.fullPatioReplacementPrice) > 0)) {
    missing.push("whole door price");
  }
  if (Number(o.numScreensCustom) > 0 && !(Number(o.customScreenPrice) > 0)) {
    missing.push("custom screen price");
  }
  if (Number(o.numPatioCustom) > 0 && !(Number(o.customPatioPrice) > 0)) {
    missing.push("custom patio price");
  }
  if (!o.customerName || !o.customerName.trim()) missing.push("customer name");
  if (!o.phone || !o.phone.trim()) missing.push("phone number");
  return missing;
}

// Genuine pending actions — not missing data, but a task that's actually yours to go do.
// Kept deliberately narrow so this doesn't become a catch-all.
const NEW_ORDER_STALE_DAYS = 3;
const WAITING_PARTS_STALE_DAYS = 7;
function getActionReasons(o, todayStr) {
  const reasons = [];
  if (o.fullPatioReplacement && o.metroStatus === "need_to_order") {
    reasons.push("Place Metro Screenworks order");
  }
  if (o.fullPatioReplacement && o.metroStatus === "ready_for_pickup") {
    reasons.push("Pick up from Metro Screenworks");
  }
  if (o.status === "new_order") {
    const days = daysBetween(o.dropOffDate, todayStr);
    if (days >= NEW_ORDER_STALE_DAYS) reasons.push(`Sitting unreviewed ${days}d`);
  }
  // Using dropOffDate as the reference point, same approach as the stale New Order check above —
  // there's no dedicated "entered this status on X" timestamp, so this is a reasonable proxy
  // rather than exact tracking of how long it's specifically been waiting on parts.
  if (o.status === "waiting_parts") {
    const days = daysBetween(o.dropOffDate, todayStr);
    if (days >= WAITING_PARTS_STALE_DAYS) reasons.push(`Waiting on parts ${days}d`);
  }
  // Final Steps to Close already catches this for Picked Up orders — but once something
  // is actually Closed (including via the "mark it anyway" override), nothing else ever
  // checks again, so a skipped review request could go unnoticed forever without this.
  if (o.status === "closed" && !o.reviewRequestSent) {
    reasons.push("Review request not sent yet");
  }
  return reasons;
}

// Today plus up to 13 previous days (14 total) that don't yet have a time log entry.
function getMissingTimeLogDays(timeLogs) {
  const today = todayISO();
  const logsByDate = Object.fromEntries(timeLogs.map((l) => [l.date, l.hours]));
  const days = [];
  for (let i = 0; i < 14; i++) {
    const d = addDays(today, -i);
    if (logsByDate[d] === undefined) days.push(d);
  }
  return days;
}

// Flags a month once its own last calendar day has actually arrived (not just once we've
// moved into the next month) — checked back 6 months plus the current one. Never flags
// anything before August 2026, the month this tracker actually started being used for real.
function getMissingExpenseMonths(monthlyExpenses) {
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const loggedByMonth = Object.fromEntries(monthlyExpenses.map((m) => [m.month, m.total]));
  const months = [];
  for (let i = 0; i <= 6; i++) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
    if (key < "2026-08") continue;
    const lastDayOfMonth = new Date(d.getFullYear(), d.getMonth() + 1, 0);
    if (today < lastDayOfMonth) continue;
    if (loggedByMonth[key] === undefined) {
      months.push({ key, label: d.toLocaleDateString("en-US", { month: "long", year: "numeric" }) });
    }
  }
  return months;
}

function addDays(dateStr, days) {
  const d = new Date(dateStr + "T00:00:00");
  d.setDate(d.getDate() + Number(days || 0));
  return d.toISOString().slice(0, 10);
}

// Shared timing/overdue logic used by the card, dashboard, and pickup tab.
// Patio-involved orders (screens, full replacement, or both) are never flagged overdue —
// subcontractor lead times make a hard alarm misleading. Screen-only orders use the 7-day default.
function getOrderTiming(order, rates) {
  const daysOpen = daysBetween(order.dropOffDate, todayISO());
  const hasScreens = (Number(order.numScreens) || 0) + (Number(order.numScreensPremium) || 0) + (Number(order.numScreensCustom) || 0) > 0;
  const hasPatio = Number(order.patioDoorCount) > 0 || !!order.fullPatioReplacement;

  if (hasPatio && hasScreens) {
    return { daysOpen, dueDate: null, isOverdue: false, showDue: false };
  }
  if (hasPatio) {
    const dueDate = addDays(order.dropOffDate, rates.patioTurnaroundDays);
    return { daysOpen, dueDate, isOverdue: false, showDue: true };
  }
  const dueDate = addDays(order.dropOffDate, rates.turnaroundDays);
  const isOverdue = order.status !== "picked_up" && daysOpen > rates.turnaroundDays;
  return { daysOpen, dueDate, isOverdue, showDue: true };
}

/* ---------------------------------- HELPERS ---------------------------------- */
const todayISO = () => new Date().toISOString().slice(0, 10);
const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 7);

function formatDate(str) {
  if (!str) return "—";
  const d = new Date(str + "T00:00:00");
  if (isNaN(d)) return "—";
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

function formatMoney(n) {
  return (Number(n) || 0).toLocaleString("en-US", { style: "currency", currency: "USD" });
}

function formatPhone(raw) {
  const digits = (raw || "").replace(/\D/g, "");
  if (digits.length === 10) {
    return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}`;
  }
  return raw || "";
}

function formatPhoneInput(value) {
  const digits = (value || "").replace(/\D/g, "").slice(0, 10);
  const len = digits.length;
  if (len === 0) return "";
  if (len < 4) return `(${digits}`;
  if (len < 7) return `(${digits.slice(0, 3)}) ${digits.slice(3)}`;
  return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}`;
}

// Attempts to open a specific Google Voice conversation. This exact query-param format is
// commonly used but not officially documented by Google, so it isn't guaranteed to keep
// working — if it just opens your general Voice inbox instead of the right thread, that's why.
function voiceLink(raw) {
  const digits = (raw || "").replace(/\D/g, "");
  if (digits.length === 10) {
    return `https://voice.google.com/u/0/messages?itemId=t.%2B1${digits}`;
  }
  if (digits.length === 11 && digits.startsWith("1")) {
    return `https://voice.google.com/u/0/messages?itemId=t.%2B${digits}`;
  }
  return "https://voice.google.com/u/0/messages";
}

function daysBetween(a, b) {
  const d1 = new Date(a + "T00:00:00");
  const d2 = new Date(b + "T00:00:00");
  return Math.round((d2 - d1) / 86400000);
}

// Counts calendar days spanned by a {start, end} Date-object range, ignoring whatever
// time-of-day each boundary happens to carry — a raw ms-difference divide rounds incorrectly
// when start is midnight but end is 23:59:59, which was inflating month lengths by a day.
function calendarDaysInRange(start, end) {
  const s = new Date(start.getFullYear(), start.getMonth(), start.getDate());
  const e = new Date(end.getFullYear(), end.getMonth(), end.getDate());
  return Math.round((e - s) / 86400000) + 1;
}

// Reports are anchored to pickup date, since that's exactly when payment actually comes in —
// this matches how income is really recognized for tax/bookkeeping purposes. Falls back to
// drop-off date for any order that hasn't been picked up yet, so in-progress work still shows
// up somewhere rather than disappearing from Reports entirely until it's fully wrapped up.
function reportAnchorDate(order) {
  return order.pickupDate || order.dropOffDate;
}

const BUSINESS_ADDRESS = "514 E. Irish Ave, Littleton, CO 80122";

// Builds a standard .ics calendar file for a scheduled pickup, as an all-day event on the
// pickup date. iOS Safari recognizes the text/calendar MIME type on a data URI and hands it
// directly to the native Calendar app's "Add Event" screen — no separate app or download step.
function buildPickupICS(order) {
  const dateDigits = order.pickupDate.replace(/-/g, "");
  const endDate = addDays(order.pickupDate, 1).replace(/-/g, "");
  const stamp = new Date().toISOString().replace(/[-:]/g, "").split(".")[0] + "Z";
  const total = (Number(order.screenPrice) || 0) + (Number(order.patioDoorPrice) || 0) + (Number(order.fullPatioReplacementPrice) || 0);
  const descParts = [`Phone: ${formatPhone(order.phone) || "—"}`];
  if (order.pickupTimeNote) descParts.push(`Time: ${order.pickupTimeNote}`);
  descParts.push(`Total: ${formatMoney(total)}`);
  const escape = (s) => (s || "").replace(/[\\;,]/g, (c) => "\\" + c).replace(/\n/g, "\\n");
  const lines = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//Arkay Window Screens Tracker//EN",
    "BEGIN:VEVENT",
    `UID:${order.id}@arkaywindowscreens`,
    `DTSTAMP:${stamp}`,
    `DTSTART;VALUE=DATE:${dateDigits}`,
    `DTEND;VALUE=DATE:${endDate}`,
    `SUMMARY:${escape(`Pickup: ${order.customerName}`)}`,
    `DESCRIPTION:${escape(descParts.join("\n"))}`,
    `LOCATION:${escape(BUSINESS_ADDRESS)}`,
    "END:VEVENT",
    "END:VCALENDAR",
  ];
  return lines.join("\r\n");
}

