/* ---------------------------------- COMPLETE PANEL ---------------------------------- */
function CompletePanel({ orders, onEdit, onDelete, onStatusChange, rates, onLookupCustomer }) {
  const [viewingOrder, setViewingOrder] = useState(null);
  const completed = orders
    .filter((o) => o.status === "closed")
    .sort((a, b) => (a.dropOffDate < b.dropOffDate ? 1 : a.dropOffDate > b.dropOffDate ? -1 : 0));

  // Group by month for a growing list that stays easy to scan, same pattern as the
  // Financials tab's monthly breakdown.
  const groups = [];
  completed.forEach((o) => {
    const d = new Date(o.dropOffDate + "T00:00:00");
    const key = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
    let group = groups.find((g) => g.key === key);
    if (!group) {
      group = { key, label: d.toLocaleDateString("en-US", { month: "long", year: "numeric" }), orders: [] };
      groups.push(group);
    }
    group.orders.push(o);
  });

  // How many total past orders (any status) share this customer's name or phone — used for
  // the repeat-customer tag. More than 1 means they've been back before.
  const countForCustomer = (order) => {
    const nameQ = (order.customerName || "").trim().toLowerCase();
    const phoneQ = (order.phone || "").replace(/\D/g, "");
    if (!nameQ && !phoneQ) return 1;
    return orders.filter((o) => {
      const nameMatch = nameQ && (o.customerName || "").trim().toLowerCase() === nameQ;
      const phoneMatch = phoneQ.length >= 7 && (o.phone || "").replace(/\D/g, "") === phoneQ;
      return nameMatch || phoneMatch;
    }).length;
  };

  return (
    <div className="rounded-lg border bg-white p-4" style={{ borderColor: COLORS.line }}>
      <p className="text-xs font-display uppercase tracking-wide mb-1" style={{ color: COLORS.inkSoft }}>Complete — most recent first</p>
      {completed.length === 0 ? (
        <p className="text-sm font-body py-6 text-center" style={{ color: COLORS.inkSoft }}>Nothing closed out yet.</p>
      ) : (
        <div className="space-y-5">
          {groups.map((group) => (
            <div key={group.key}>
              <p className="font-display text-xs uppercase tracking-wide mb-1 mt-2" style={{ color: COLORS.inkSoft }}>{group.label}</p>
              <div>
                {group.orders.map((order) => {
                  const total = (Number(order.screenPrice) || 0) + (Number(order.patioDoorPrice) || 0) + (Number(order.fullPatioReplacementPrice) || 0);
                  const repeatCount = countForCustomer(order);
                  return (
                    <div key={order.id} className="flex flex-wrap items-center gap-x-3 gap-y-1 py-3 border-b" style={{ borderColor: COLORS.line }}>
                      <div className="flex-1 min-w-[140px]">
                        <p className="font-display text-sm truncate" style={{ color: COLORS.ink }}>{order.customerName}</p>
                        <a href={voiceLink(order.phone)} target="_blank" rel="noopener noreferrer" className="font-body text-xs underline" style={{ color: COLORS.slate }}>
                          {formatPhone(order.phone) || "—"}
                        </a>
                      </div>
                      {repeatCount > 1 && (
                        <button
                          onClick={() => onLookupCustomer(order.customerName || order.phone)}
                          className="font-display text-xs rounded-full px-2 py-0.5"
                          style={{ background: "#EAF3F9", color: COLORS.slate }}
                          title="See this customer's full order history"
                        >
                          Repeat ×{repeatCount}
                        </button>
                      )}
                      <span className="font-body text-xs" style={{ color: COLORS.inkSoft }}>Dropped off {formatDate(order.dropOffDate)}</span>
                      <span className="font-body text-sm font-semibold" style={{ color: COLORS.ink }}>{formatMoney(total)}</span>
                      <button onClick={() => setViewingOrder(order)} className="p-1 rounded hover:bg-black/5" aria-label="View order details" title="View order">
                        <Eye size={14} color={COLORS.inkSoft} />
                      </button>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}
      {viewingOrder && <OrderViewModal order={viewingOrder} rates={rates} onClose={() => setViewingOrder(null)} onEdit={onEdit} onDelete={onDelete} allOrders={orders} onLookupCustomer={onLookupCustomer} />}
    </div>
  );
}

